import React, { useEffect, useMemo, useState } from 'react';
import {
  Calendar,
  Clock,
  User,
  Mail,
  MapPin,
  X,
} from 'lucide-react';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

function formatDateTime(scheduledAt, duration = 30) {
  const date = new Date(scheduledAt);
  const dateLabel = date.toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  });

  const startTime = date.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  });

  const endDate = new Date(date.getTime() + duration * 60000);
  const endTime = endDate.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  });

  return {
    dateLabel,
    timeLabel: `${startTime} - ${endTime} (${duration} min)`,
  };
}

function Meetings() {
  const [meetings, setMeetings] = useState([]);
  const [tab, setTab] = useState('upcoming');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBookings = async () => {
      try {
        const response = await fetch(`${API_BASE}/bookings`);
        if (!response.ok) {
          throw new Error('Could not load bookings');
        }
        const data = await response.json();

        const transformed = data.map((booking) => {
          const duration = booking.event_duration || 30;
          const { dateLabel, timeLabel } = formatDateTime(booking.scheduled_at, duration);
          const now = new Date();
          const scheduledDate = new Date(booking.scheduled_at);

          return {
            id: booking.id,
            eventTitle: booking.event_title || 'Meeting',
            attendee: booking.name,
            email: booking.email,
            dateLabel,
            timeLabel,
            location: 'Video call',
            bucket: scheduledDate >= now ? 'upcoming' : 'past',
            duration,
          };
        });

        setMeetings(transformed);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    fetchBookings();
  }, []);

  const upcomingCount = useMemo(
    () => meetings.filter((m) => m.bucket === 'upcoming').length,
    [meetings]
  );
  const pastCount = useMemo(
    () => meetings.filter((m) => m.bucket === 'past').length,
    [meetings]
  );

  const visible = meetings.filter((m) => m.bucket === tab);

  const dismiss = async (id) => {
    try {
      const resp = await fetch(`${API_BASE}/bookings/${id}`, { method: 'DELETE' });
      if (!resp.ok) {
        throw new Error('Could not cancel booking');
      }
      setMeetings((list) => list.filter((m) => m.id !== id));
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return (
      <div className="page-meetings">
        <header className="page-header">
          <div>
            <h1 className="page-title">Meetings</h1>
            <p className="page-subtitle">View and manage your scheduled meetings</p>
          </div>
        </header>
        <p>Loading meetings...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="page-meetings">
        <header className="page-header">
          <div>
            <h1 className="page-title">Meetings</h1>
            <p className="page-subtitle">View and manage your scheduled meetings</p>
          </div>
        </header>
        <p className="error-message">{error}</p>
      </div>
    );
  }

  return (
    <div className="page-meetings">
      <header className="page-header">
        <div>
          <h1 className="page-title">Meetings</h1>
          <p className="page-subtitle">View and manage your scheduled meetings</p>
        </div>
      </header>

      <div className="tab-pills" role="tablist" aria-label="Meeting filters">
        <button
          type="button"
          role="tab"
          aria-selected={tab === 'upcoming'}
          className={`tab-pill ${tab === 'upcoming' ? 'tab-pill--active' : ''}`}
          onClick={() => setTab('upcoming')}
        >
          <Calendar size={18} strokeWidth={2} aria-hidden />
          Upcoming ({upcomingCount})
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={tab === 'past'}
          className={`tab-pill ${tab === 'past' ? 'tab-pill--active' : ''}`}
          onClick={() => setTab('past')}
        >
          <Clock size={18} strokeWidth={2} aria-hidden />
          Past &amp; Cancelled ({pastCount})
        </button>
      </div>

      <div className="meeting-list">
        {visible.length === 0 && (
          <p className="empty-hint">No meetings in this view.</p>
        )}
        {visible.map((m) => (
          <article key={m.id} className="meeting-card">
            <div className="meeting-card-head">
              <h2 className="meeting-card-title">{m.eventTitle}</h2>
              {tab === 'upcoming' && (
                <button
                  type="button"
                  className="btn-icon-muted meeting-dismiss"
                  aria-label="Cancel or remove meeting"
                  onClick={() => dismiss(m.id)}
                >
                  <X size={18} strokeWidth={2} />
                </button>
              )}
            </div>
            <ul className="meeting-details">
              <li>
                <Calendar size={16} strokeWidth={2} aria-hidden />
                {m.dateLabel}
              </li>
              <li>
                <Clock size={16} strokeWidth={2} aria-hidden />
                {m.timeLabel}
              </li>
              <li>
                <User size={16} strokeWidth={2} aria-hidden />
                {m.attendee}
              </li>
              <li>
                <Mail size={16} strokeWidth={2} aria-hidden />
                {m.email}
              </li>
              <li>
                <MapPin size={16} strokeWidth={2} aria-hidden />
                {m.location}
              </li>
            </ul>
          </article>
        ))}
      </div>
    </div>
  );
}

export default Meetings;
